local M = {}
local function lines(name) local file=assert(io.open("input/"..name));local out={};for line in file:lines() do out[#out+1]=line end;file:close();return out end
local function csv(line) local fields={};for field in (line..","):gmatch("(.-),") do fields[#fields+1]=field end;return fields end
local function rows(name,offset)
 local data=lines(name);local header=csv(data[1]);local features={};for j=2,#header-2 do features[#features+1]=header[j] end;local out={}
 for j=2,#data do local f=csv(data[j]);local r={id=f[1],label=f[#f-1],values={},target=0,has_target=f[#f]~="",index=offset+#out+1};for k=2,#f-2 do r.values[#r.values+1]=assert(tonumber(f[k])) end;if r.has_target then r.target=assert(tonumber(f[#f])) end;out[#out+1]=r end;return features,out
end
function M.read()
 local features,train=rows("train.csv",0);local _,test=rows("test.csv",#train);local s={}
 for _,line in ipairs(lines("params.txt")) do local fields={};for word in line:gmatch("%S+") do fields[#fields+1]=word end;local key=table.remove(fields,1);if key=="FOLDS" or key=="EDIT_K" or key=="TOP" then s[key]=tonumber(fields[1]) elseif key=="K_VALUES" or key=="CURVE" or key=="BINS" then s[key]={};for _,word in ipairs(fields) do s[key][#s[key]+1]=tonumber(word) end else s[key]=fields end end
 local found,labels={},{};for _,r in ipairs(train) do found[r.label]=true end;for label in pairs(found) do labels[#labels+1]=label end;table.sort(labels)
 return {features=features,labels=labels,train=train,test=test,settings=s}
end
return M

local M = {}
function M.fixed(v,places) local text=string.format("%."..(places or 4).."f",v);if text:sub(1,1)=="-" and tonumber(text)==0 then return text:sub(2) end;return text end
function M.four(v) return tonumber(M.fixed(v,4)) end
function M.ratio(a,b) return string.format("%d/%d %s",a,b,M.fixed(a/b)) end
function M.fraction(a,b)
 if b==0 then return "- -" end;local x,y=a,b;while y~=0 do x,y=y,x%y end;return string.format("%d/%d %s",a//x,b//x,M.fixed(a/b))
end
function M.write(name,lines) local file=assert(io.open("output/"..name,"w"));for _,line in ipairs(lines) do file:write(line,"\n") end;file:close() end
return M

local M = {}
function M.compute(rows,method)
 local s={centers={},scales={}}
 for j=1,#rows[1].values do
  if method=="standard" then local total=0.0;for _,r in ipairs(rows) do total=total+r.values[j] end;local center=total/#rows;s.centers[j]=center;s.scales[j]=0.0;if #rows>1 then local squares=0.0;for _,r in ipairs(rows) do local d=r.values[j]-center;squares=squares+d*d end;s.scales[j]=math.sqrt(squares/(#rows-1)) end
  else local low,high=rows[1].values[j],rows[1].values[j];for _,r in ipairs(rows) do low=math.min(low,r.values[j]);high=math.max(high,r.values[j]) end;s.centers[j]=low;s.scales[j]=high-low end
 end;return s
end
function M.transform(s,row,features)
 local out={};for _,i in ipairs(features) do out[#out+1]=s.scales[i]>0 and (row.values[i]-s.centers[i])/s.scales[i] or 0.0 end;return out
end
return M
